/*---------------------------------------------------------------------*/
/*    Imports                                                          */
/*---------------------------------------------------------------------*/
import { exec, execSync } from "child_process";

/*---------------------------------------------------------------------*/
/*    system ...                                                       */
/*---------------------------------------------------------------------*/
export function system(cmd) {
   return new Promise((res, rej) => {
      exec(cmd, (error, stdout, stderr) => {
         if (!error) {
            res(stdout.toString());
         } else {
            rej({status: error, data: stderr.toString()});
         }
      });
   })
}

/*---------------------------------------------------------------------*/
/*    systemSync ...                                                   */
/*---------------------------------------------------------------------*/
export function systemSync(cmd) {
   return execSync(cmd);
}
